if not isinstance(equation, str) or not equation.strip():
    raise ValueError('equation must be a non-empty string')
if not isinstance(variable, str) or not variable.strip():
    raise ValueError('variable must be a non-empty string')

try:
    if '=' in equation:
        left, right = equation.split('=', 1)
        expression = sympify(left) - sympify(right)
    else:
        expression = sympify(equation)
    var = sympify(variable)
except Exception as exc:
    raise ValueError(f'Invalid equation or variable: {exc}') from exc

try:
    result = solve(expression, var, dict=True)
except Exception as exc:
    raise ValueError(f'Could not solve equation: {exc}') from exc

if isinstance(result, dict):
    result_items = [result]
elif isinstance(result, (list, tuple, set)):
    result_items = list(result)
elif result is None:
    result_items = []
else:
    result_items = [result]

solutions = []
for item in result_items:
    if isinstance(item, dict):
        converted = {str(key): str(value) for key, value in item.items()}
        key = str(var)
        if key in converted:
            solutions.append(converted[key])
        elif converted:
            solutions.append(next(iter(converted.values())))
        else:
            solutions.append(str(var))
    elif isinstance(item, (list, tuple)):
        if len(item) == 1:
            solutions.append(str(item[0]))
        else:
            solutions.append(str(item))
    else:
        solutions.append(str(item))

return {
    'equation': equation,
    'variable': variable,
    'solutions': solutions,
    'solution_count': len(solutions),
    'solutions_display': str(solutions),
}

if not isinstance(equations, str) or not equations.strip():
    raise ValueError('equations must be a non-empty string')
if not isinstance(variables, str) or not variables.strip():
    raise ValueError('variables must be a non-empty string')

lines = [line.strip() for line in equations.splitlines()]
lines = [line for line in lines if line]
if not lines:
    raise ValueError('equations must contain at least one non-empty equation')

var_names = [part.strip() for part in variables.split(',')]
if not var_names or any(not name for name in var_names):
    raise ValueError('variables must be a comma-separated list of non-empty names')

try:
    expressions = []
    for line in lines:
        if '=' in line:
            left, right = line.split('=', 1)
            expressions.append(sympify(left) - sympify(right))
        else:
            expressions.append(sympify(line))
    var_symbols = [sympify(name) for name in var_names]
except Exception as exc:
    raise ValueError(f'Invalid equations or variables: {exc}') from exc

try:
    result = solve(expressions, *var_symbols, dict=True)
except Exception as exc:
    raise ValueError(f'Could not solve system: {exc}') from exc

if isinstance(result, dict):
    result_items = [result]
elif isinstance(result, (list, tuple, set)):
    result_items = list(result)
elif result is None:
    result_items = []
else:
    result_items = [result]

solutions = []
for item in result_items:
    if isinstance(item, dict):
        solutions.append({str(key): str(value) for key, value in item.items()})
    elif isinstance(item, (list, tuple)):
        if len(item) == len(var_symbols):
            solutions.append({str(var): str(value) for var, value in zip(var_symbols, item)})
        else:
            solutions.append(str(item))
    else:
        solutions.append(str(item))

return {
    'equations': lines,
    'variables': var_names,
    'solutions': solutions,
    'solution_count': len(solutions),
    'solutions_display': str(solutions),
}
